var enumPatchOpKindValues = []string{"", "add", "remove", "replace", "move", "copy", "test"}
var enumSandboxAccessValues = []string{"", "ro", "rx", "rw", "rwx"}
var enumSymbolFormatValues = []string{"", "scip"}
